import hashlib, importlib.util, json, pathlib, sqlite3, sys, tempfile, unittest
spec=importlib.util.spec_from_file_location('battery',pathlib.Path(__file__).with_name('battery.py')); b=importlib.util.module_from_spec(spec); spec.loader.exec_module(b)
class BatteryTest(unittest.TestCase):
 def setUp(self):
  self.tmp=tempfile.TemporaryDirectory(); self.root=pathlib.Path(self.tmp.name); self.db=b.connect(self.root/'private'/'batteries.sqlite'); self.image=b'original image bytes'; self.sha=hashlib.sha256(self.image).hexdigest(); self.cache=self.root/'cache'; self.cache.mkdir(); (self.cache/self.sha).write_bytes(self.image)
  post={'post_id':7,'title':'title','text':'body','human_labels':[{'label':'x','content_hash':'old'}],'assets':[{'index':0,'role':'src','kind':'image','source_url':'https://pbs.twimg.com/a','status':'ready','sha256':self.sha,'size':len(self.image),'mime':'image/jpeg'}]}; self.manifest=self.root/'manifest.jsonl'; self.manifest.write_text(json.dumps(post)+'\n')
  self.adapter=self.root/'adapter.py'; self.adapter.write_text('import json,sys\nr=json.load(sys.stdin)\nprint(json.dumps({"seen_iteration":r["iteration"],"coverage":r["coverage"]}))\n')
  self.config={'iterations':2,'tools':[{'id':'rating','task':'rating','policy_version':'suggestive-r-explicit-x-v1','input':'multimodal','model':'qwen','model_digest':'abc','argv':[sys.executable,str(self.adapter)]},{'id':'objects','task':'object','input':'image','model':'mobile','model_digest':'def','argv':[sys.executable,str(self.adapter)]}]}
 def tearDown(self): self.db.close(); self.tmp.cleanup()
 def test_iterations_resume_and_separate_tools(self):
  run=b.create(self.db,'trial',self.manifest,self.config); self.assertEqual(b.execute(self.db,run,self.cache,'https://example.test',max_jobs=1),1); self.assertEqual(b.execute(self.db,run,self.cache,'https://example.test'),3); self.assertEqual(b.execute(self.db,run,self.cache,'https://example.test'),0)
  self.assertEqual(self.db.execute('select count(*) from attempts').fetchone()[0],4); results=self.db.execute('select j.tool_id,j.iteration,a.result from jobs j join attempts a on a.job_id=j.id order by j.tool_id,j.iteration').fetchall(); self.assertEqual([(r[0],r[1]) for r in results],[('objects',1),('objects',2),('rating',1),('rating',2)]); self.assertFalse(json.loads(results[0][2])['coverage']['complete']); self.assertTrue(json.loads(results[2][2])['coverage']['complete']); self.assertEqual(b.summary(self.db,run)['tools'][0]['held_out_human_accuracy']['samples'],0)
  second=b.create(self.db,'repeat',self.manifest,self.config); self.assertNotEqual(run,second); self.assertEqual(self.db.execute('select count(*) from attempts').fetchone()[0],4); b.execute(self.db,second,self.cache,'https://example.test'); comparisons=b.compare(self.db,run,second)['comparisons']; self.assertEqual(len(comparisons),2); self.assertTrue(all(c['matched_post_iterations']==2 for c in comparisons))
 def test_hash_mismatch_and_retry_preserve_attempts(self):
  (self.cache/self.sha).write_bytes(b'wrong'); run=b.create(self.db,'retry',self.manifest,self.config); b.execute(self.db,run,self.cache,'https://example.test',max_jobs=1); self.assertEqual(self.db.execute('select status from jobs order by id limit 1').fetchone()[0],'error'); (self.cache/self.sha).write_bytes(self.image); b.execute(self.db,run,self.cache,'https://example.test',max_jobs=1,retry_errors=True); self.assertEqual(self.db.execute('select status from jobs order by id limit 1').fetchone()[0],'done'); self.assertEqual(self.db.execute('select status from attempts order by id').fetchall(),[('error',),('done',)])
 def test_held_out_accuracy_requires_matching_review_and_image(self):
  post=json.loads(self.manifest.read_text()); post['human_labels']=[{'label':'r','content_hash':'review','snapshot_verified':True,'policy_version':'suggestive-r-explicit-x-v1','artifact_sha256':[self.sha]}]; self.manifest.write_text(json.dumps(post)+'\n')
  self.adapter.write_text('import json,sys\nr=json.load(sys.stdin)\nprint(json.dumps({"rating":"r","uncertain":False,"prepared_image_sha256":r["tool"]["expected"]}))\n')
  self.config['tools'][0]['expected']=self.sha
  run=b.create(self.db,'scored',self.manifest,self.config); self.db.execute("update inputs set split='held_out' where battery_id=?",(run,)); self.db.commit(); b.execute(self.db,run,self.cache,'https://example.test')
  report=b.summary(self.db,run)['tools'][0]['held_out_human_accuracy']; self.assertEqual(report['samples'],1); self.assertEqual(report['confusion_matrix']['r']['r'],1); self.assertEqual(report['per_class']['r']['recall'],1)
  value=json.loads(self.db.execute('select payload from inputs where battery_id=?',(run,)).fetchone()[0]); value['human_labels'][0]['policy_version']='other'; self.db.execute('update inputs set payload=? where battery_id=?',(json.dumps(value),run)); self.db.commit(); self.assertEqual(b.summary(self.db,run)['tools'][0]['held_out_human_accuracy']['samples'],0); value['human_labels'][0]['policy_version']='suggestive-r-explicit-x-v1'; value['human_labels'][0]['snapshot_verified']=False; self.db.execute('update inputs set payload=? where battery_id=?',(json.dumps(value),run)); self.db.commit(); self.assertEqual(b.summary(self.db,run)['tools'][0]['held_out_human_accuracy']['samples'],0)
 def test_changed_adapter_is_rejected_on_resume(self):
  run=b.create(self.db,'fingerprint',self.manifest,self.config); self.adapter.write_text('print("changed")\n'); b.execute(self.db,run,self.cache,'https://example.test',max_jobs=1); self.assertEqual(self.db.execute('select status from jobs where battery_id=? order by id limit 1',(run,)).fetchone()[0],'error')
 def test_content_hash_ignores_review_labels(self):
  run=b.create(self.db,'first',self.manifest,self.config); post=json.loads(self.manifest.read_text()); post['human_labels'].append({'label':'r','content_hash':'new'}); self.manifest.write_text(json.dumps(post)+'\n'); other=b.create(self.db,'second',self.manifest,self.config); self.assertEqual(self.db.execute('select input_sha256 from inputs where battery_id=?',(run,)).fetchone(),self.db.execute('select input_sha256 from inputs where battery_id=?',(other,)).fetchone())
if __name__=='__main__': unittest.main()
